import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ChevronLeft } from 'lucide-react';
import './Transport.css';

const Transport = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('Booking'); // 状态：Booking 或 Timetable
  const [hasRecord, setHasRecord] = useState(false); // 模拟是否有记录

  return (
    <div className="transport-container">
      {/* 顶部导航栏 */}
      <nav className="top-nav-bar">
        <div className="back-arrow-wrapper" onClick={() => navigate('/')}>
          <ChevronLeft size={24} color="#ffffff" strokeWidth={2.5} />
        </div>
        <span className="nav-title">Transport</span>
      </nav>

      <div className="transport-content">
        {/* 顶部的两个功能按钮 */}
        <div className="transport-tabs">
          <button 
            className={`transport-tab-btn ${activeTab === 'Booking' ? 'active' : ''}`}
            onClick={() => setActiveTab('Booking')}
          >
            Booking
          </button>
          <button 
            className={`transport-tab-btn ${activeTab === 'Timetable' ? 'active' : ''}`}
            onClick={() => setActiveTab('Timetable')}
          >
            Timetable
          </button>
        </div>

        {/* 条件渲染：如果没有记录，显示图片 */}
        {!hasRecord ? (
          <div className="empty-state">
            <img 
              src="/icon_img/transportpage.png" 
              alt="No Record" 
              className="empty-image"
            />
          </div>
        ) : (
          <div className="record-list">
            {/* 这里将来放置记录列表 */}
          </div>
        )}
      </div>
    </div>
  );
};

export default Transport;
